import{_ as e,o,c as a,a0 as r}from"./chunks/framework.C0WKPwzJ.js";const p=JSON.parse('{"title":"Client guide","description":"How to use Autodevelop day to day — install, tickets, confirmed mail, and ship phrases.","frontmatter":{"title":"Client guide","description":"How to use Autodevelop day to day — install, tickets, confirmed mail, and ship phrases."},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1788171427000}'),d={name:"guide.md"};function i(n,t,s,l,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="client-guide" tabindex="-1">Client guide <a class="header-anchor" href="#client-guide" aria-label="Permalink to &quot;Client guide&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>This page is the handbook you can send to a team. It covers how the product is used after install.</p><h2 id="day-to-day" tabindex="-1">Day to day <a class="header-anchor" href="#day-to-day" aria-label="Permalink to &quot;Day to day&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>What you do</th><th>What you say</th></tr></thead><tbody><tr><td>Install once</td><td>Import the Cursor plugin, then reload the window</td><td><code>/import-autodevelop</code></td></tr><tr><td>Sign in</td><td>Authorize this machine and install the organization pack</td><td><code>pnpm autodevelop login</code> or <code>npx @devprecated/autodevelop login</code></td></tr><tr><td>Connect GitHub</td><td>An operator installs the Autodevelop GitHub App on the GitHub org</td><td>Connect GitHub in the operator console</td></tr><tr><td>Check the machine</td><td>Run doctor. It never sends mail</td><td><code>pnpm doctor</code></td></tr><tr><td>File or claim work</td><td>A request becomes a numbered preview, then a board ticket</td><td><strong>create</strong>, <strong>use #N</strong>, or claim an item</td></tr><tr><td>Mail a stakeholder</td><td>Review to, subject, body-as-text, and ticket link</td><td>An explicit yes, then the confirm token</td></tr><tr><td>Ship</td><td>Land git, then deploy only after the matching phrase</td><td><code>YES PUSH TO MASTER</code>, <code>DEPLOYED TO STAGING</code>, <code>YES PUSH TO RELEASE</code>, <code>DEPLOYED TO PRODUCTION</code></td></tr></tbody></table><p>Details: <a href="./install">Install</a>, <a href="./cli">CLI</a>, <a href="./github">GitHub App</a>, <a href="./configure">Configure</a>.</p><p>Organization members who use the <strong>ticket UI</strong> are invited, then they sign in. They choose a request type (bug, improvement, tweak, new feature, new microfrontend, or new web app) and answer the questions for that type. The same UI can open from a button or link in your own product. There is no public registration.</p><p>Owners and executives sign in to the <strong>business console</strong> to review work, team activity, delivery value, usage, payment, and weekly meetings. An operator assigns what each person can do.</p><p>The Cursor plugin uses a subscription token under <strong>Plugins → Configure</strong>. That token is not a website login.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What it is for</th></tr></thead><tbody><tr><td>Tickets and the board</td><td>Turn a request into a GitHub Project issue, claim it, comment, and verify acceptance</td></tr><tr><td>Stakeholder mail</td><td>Draft allowlisted email. Hooks never send. A human confirms every draft</td></tr><tr><td>Ship</td><td>Phrase-gated git and local deploys. Staging and production stay separate unless the instance is single-branch</td></tr><tr><td>Setup</td><td>Plugin, CLI, GitHub App, instance files, and <code>pnpm doctor</code></td></tr><tr><td>In-app tickets</td><td>Open submit and “my tickets” from a button or link in your application</td></tr></tbody></table><h2 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>When</th></tr></thead><tbody><tr><td><a href="./workflows/initial-setup">Initial setup</a></td><td>First day, or mail / <code>gh</code> broke</td></tr><tr><td><a href="./workflows/create-tickets">Create tickets</a></td><td>Notes or a chat request → GitHub Project issues</td></tr><tr><td><a href="./workflows/notify-stakeholders">Notify stakeholders</a></td><td>Confirmed stakeholder mail</td></tr><tr><td><a href="./workflows/ship-to-staging">Ship to staging</a></td><td>Local staging. Phrase <code>DEPLOYED TO STAGING</code></td></tr><tr><td><a href="./workflows/ship-to-production">Ship to production</a></td><td>Production ship. Phrase <code>DEPLOYED TO PRODUCTION</code></td></tr><tr><td><a href="./workflows/when-something-breaks">When something breaks</a></td><td>Doctor, billing, preview denied</td></tr></tbody></table><h2 id="what-autodevelop-does-not-do" tabindex="-1">What Autodevelop does not do <a class="header-anchor" href="#what-autodevelop-does-not-do" aria-label="Permalink to &quot;What Autodevelop does not do&quot;">​</a></h2><ul><li><strong>No Jira, Linear, Asana, or Trello.</strong> The shipped board is GitHub Projects.</li><li><strong>No SMTP as shipped.</strong> Mail uses Firestore on the consumer Firebase project.</li><li><strong>Hooks never send mail</strong> and never invent a confirm token.</li><li><strong>Hooks never create issues</strong> in the same turn as the numbered preview.</li><li><strong>No public signup</strong> on the ticket UI. Members are invited, then they sign in.</li><li><strong>Doctor is not a deploy.</strong> <code>--fix</code> prints commands. It does not write mail.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./install">Install</a></li><li><a href="./cli">CLI</a></li><li><a href="./integration">Integration</a></li></ul>',17)])])}const g=e(d,[["render",i]]);export{p as __pageData,g as default};
